import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { getMatchId } from "../api";

// --- ВСПОМОГАТЕЛЬНЫЕ КОМПОНЕНТЫ ---

const ResultCircle = ({ res }) => {
  const colors = { W: "bg-green-500", D: "bg-yellow-500", L: "bg-red-600" };
  return (
    <span
      className={`${colors[res]} w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-black text-white shadow-lg`}
    >
      {res}
    </span>
  );
};

const getH2HScoreStyle = (score) => {
  const [h, a] = score.split(":").map(Number);
  if (h > a)
    return "bg-green-600 text-white shadow-[0_0_15px_rgba(22,163,74,0.4)]";
  if (h < a)
    return "bg-red-600 text-white shadow-[0_0_15px_rgba(220,38,38,0.4)]";
  return "bg-yellow-500 text-black shadow-[0_0_15px_rgba(234,179,8,0.4)]";
};

const StatBar = ({ label, h, a, reverse, color }) => {
  const isHomeBetter = reverse ? h < a : h > a;
  const total = (parseFloat(h) || 0) + (parseFloat(a) || 0) || 1;
  return (
    <div className="relative group">
      <div className="flex justify-between items-end mb-2">
        <span className="text-3xl font-black text-white">
          {(parseFloat(h) || 0).toFixed(2)}
        </span>
        <span className="text-[10px] font-black text-white uppercase tracking-widest mb-2 opacity-80">
          {label}
        </span>
        <span className="text-3xl font-black text-white">
          {(parseFloat(a) || 0).toFixed(2)}
        </span>
      </div>
      <div className="h-3 w-full bg-gray-800 rounded-full flex overflow-hidden p-0.5 border border-gray-700">
        <div
          className={`h-full rounded-full transition-all duration-1000 ${isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${((parseFloat(h) || 0) / total) * 100}%` }}
        ></div>
        <div
          className={`h-full rounded-full transition-all duration-1000 ${!isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${((parseFloat(a) || 0) / total) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

const HistoryList = ({ title, matches }) => (
  <div className="bg-gray-800/40 p-8 rounded-[32px] border border-white/5 h-full shadow-xl">
    <h3 className="text-xs font-black text-white uppercase tracking-[0.2em] mb-8 text-center">
      {title}
    </h3>
    <div className="space-y-4">
      {matches && matches.length > 0 ? (
        matches.map((m, i) => (
          <div
            key={i}
            className="flex items-center justify-between gap-4 bg-black/20 p-5 rounded-2xl border border-white/5 hover:border-white/10 transition-colors"
          >
            <div
              className={`text-[10px] font-black px-3 py-1 rounded-lg border ${
                m.is_home
                  ? "bg-blue-500/10 text-blue-400 border-blue-500/20"
                  : "bg-purple-500/10 text-purple-400 border-purple-500/20"
              }`}
            >
              {m.is_home ? "ДОМА" : "ГОСТИ"}
            </div>
            <div className="flex items-center gap-4 flex-grow min-w-0">
              <img
                src={m.opponent_logo}
                alt=""
                className="w-9 h-9 object-contain"
              />
              <span className="text-base font-black text-white truncate">
                {m.opponent}
              </span>
            </div>
            <div className="flex items-center gap-5">
              <span className="text-lg font-black text-white font-mono italic">
                {m.score}
              </span>
              <span
                className={`w-9 h-9 rounded-xl flex items-center justify-center text-xs font-black shadow-lg ${
                  m.res === "W"
                    ? "bg-green-500 text-white"
                    : m.res === "L"
                      ? "bg-red-600 text-white"
                      : "bg-yellow-500 text-black"
                }`}
              >
                {m.res}
              </span>
            </div>
          </div>
        ))
      ) : (
        <p className="text-sm text-gray-600 italic text-center py-6 font-black uppercase tracking-widest">
          Нет данных
        </p>
      )}
    </div>
  </div>
);

// --- ОСНОВНОЙ КОМПОНЕНТ ---

function MatchDetailPage() {
  const { matchId } = useParams();
  const [match, setMatch] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      const data = await getMatchId(matchId);
      setMatch(data);
      setLoading(false);
    };
    fetchData();
  }, [matchId]);

  if (loading)
    return (
      <div className="h-screen flex items-center justify-center bg-gray-950 text-white font-black tracking-[0.5em] uppercase animate-pulse">
        Neural analysis...
      </div>
    );
  if (!match)
    return (
      <div className="text-center p-20 text-white font-black uppercase">
        Матч не найден
      </div>
    );

  const predStyle = match.prediction
    ? match.prediction.outcome === "Win Home"
      ? { text: "Победа П1", color: "text-green-500" }
      : match.prediction.outcome === "Win Away"
        ? { text: "Победа П2", color: "text-red-600" }
        : { text: "Ничья (X)", color: "text-yellow-500" }
    : null;

  return (
    <div className="max-w-6xl mx-auto px-4 py-10 text-white font-sans space-y-12">
      {/* 1. ШАПКА МАТЧА */}
      <div className="bg-gray-900 p-10 md:p-14 rounded-[40px] border border-gray-800 shadow-2xl flex flex-col md:flex-row justify-between items-center relative overflow-hidden">
        {/* ХОЗЯЕВА */}
        <div className="flex flex-col items-center w-full md:w-2/5">
          <div className="text-[11px] font-black text-yellow-500 bg-gray-800 px-5 py-2 rounded-full mb-6 tracking-widest border border-gray-700 uppercase shadow-lg">
            ELO: {Math.round(match.homeTeam.elo)}
          </div>
          <img
            src={match.homeTeam.logo_url}
            className="h-32 w-32 md:h-44 md:w-44 object-contain mb-6 drop-shadow-[0_0_20px_rgba(255,255,255,0.1)]"
            alt=""
          />
          <h1 className="text-3xl md:text-4xl font-black uppercase tracking-tighter text-center leading-none text-white">
            {match.homeTeam.name_ru || match.homeTeam.name}
          </h1>
          <div className="flex gap-2 mt-6">
            {match.homeTeam.stats_last_5.form.map((r, i) => (
              <ResultCircle key={i} res={r} />
            ))}
          </div>
        </div>

        {/* ЦЕНТРАЛЬНЫЙ БЛОК: СЧЕТ ИЛИ ВРЕМЯ */}
        <div className="my-10 md:my-0 text-center flex flex-col items-center justify-center">
          {match.status === "FINISHED" ? (
            <div className="flex flex-col items-center animate-in fade-in zoom-in duration-700">
              <span className="text-[10px] font-black text-yellow-500 uppercase tracking-[0.3em] mb-3">
                Завершено
              </span>
              <div className="text-6xl md:text-7xl font-black text-white bg-white/10 px-10 py-4 rounded-[32px] border border-white/20 shadow-[0_0_30px_rgba(255,255,255,0.1)] tracking-tighter italic">
                {match.score.home} : {match.score.away}
              </div>
            </div>
          ) : (
            <>
              <span className="text-7xl font-black text-white opacity-5 italic uppercase tracking-tighter leading-none">
                VS
              </span>
              <div className="text-3xl font-black text-white mt-4 tracking-tight">
                {new Date(match.utcDate).toLocaleTimeString([], {
                  hour: "2-digit",
                  minute: "2-digit",
                })}
              </div>
              <div className="text-xs font-bold text-gray-400 uppercase tracking-widest mt-1">
                {new Date(match.utcDate).toLocaleDateString("ru-RU")}
              </div>
            </>
          )}
        </div>

        {/* ГОСТИ */}
        <div className="flex flex-col items-center w-full md:w-2/5">
          <div className="text-[11px] font-black text-yellow-500 bg-gray-800 px-5 py-2 rounded-full mb-6 tracking-widest border border-gray-700 uppercase shadow-lg">
            ELO: {Math.round(match.awayTeam.elo)}
          </div>
          <img
            src={match.awayTeam.logo_url}
            className="h-32 w-32 md:h-44 md:w-44 object-contain mb-6 drop-shadow-[0_0_20px_rgba(255,255,255,0.1)]"
            alt=""
          />
          <h1 className="text-3xl md:text-4xl font-black uppercase tracking-tighter text-center leading-none text-white">
            {match.awayTeam.name_ru || match.awayTeam.name}
          </h1>
          <div className="flex gap-2 mt-6">
            {match.awayTeam.stats_last_5.form.map((r, i) => (
              <ResultCircle key={i} res={r} />
            ))}
          </div>
        </div>
      </div>

      {/* 2. ПРОГНОЗ НЕЙРОСЕТИ */}
      {match.prediction && (
        <div className="bg-gray-900 rounded-[32px] p-10 border border-gray-800 shadow-2xl">
          <h2 className="text-xs font-black text-red-600 uppercase tracking-[0.5em] mb-12 text-center">
            Neural Prediction Engine
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-10 items-stretch relative z-10">
            <div className="bg-black/40 p-8 rounded-[32px] border border-gray-800 flex flex-col justify-center">
              <div className="flex justify-between mb-4 text-xs font-black uppercase text-white">
                <span>П1: {match.prediction.prob_home}%</span>
                <span>X: {match.prediction.prob_draw}%</span>
                <span>П2: {match.prediction.prob_away}%</span>
              </div>
              <div className="h-6 w-full bg-gray-800 rounded-full overflow-hidden flex p-1 border border-gray-700 shadow-inner">
                <div
                  className="bg-green-500 h-full rounded-l-full"
                  style={{ width: `${match.prediction.prob_home}%` }}
                ></div>
                <div
                  className="bg-yellow-500 h-full"
                  style={{ width: `${match.prediction.prob_draw}%` }}
                ></div>
                <div
                  className="bg-red-600 h-full rounded-r-full"
                  style={{ width: `${match.prediction.prob_away}%` }}
                ></div>
              </div>
            </div>

            <div className="flex flex-col items-center justify-center p-8 bg-gray-800/30 rounded-[32px] border border-gray-800 text-center">
              <span
                className={`text-2xl font-black uppercase mb-4 tracking-widest ${predStyle.color}`}
              >
                {predStyle.text}
              </span>
              <span className="text-[10px] font-black text-white opacity-40 uppercase mb-4 tracking-widest">
                Вероятный счет
              </span>
              <span className="text-7xl font-black text-white italic tracking-tighter leading-none">
                {match.prediction.exact_score}
              </span>
            </div>

            <div className="bg-black/40 p-8 rounded-[32px] border border-gray-800 flex flex-col justify-center">
              <div className="flex justify-between mb-4 text-xs font-black uppercase text-white">
                <span>БОЛЬШЕ: {match.prediction.total_over_2_5}%</span>
                <span>
                  МЕНЬШЕ: {(100 - match.prediction.total_over_2_5).toFixed(1)}%
                </span>
              </div>
              <div className="h-6 w-full bg-gray-800 rounded-full overflow-hidden flex p-1 border border-gray-700 shadow-inner">
                <div
                  className="bg-red-600 h-full rounded-l-full shadow-[0_0_15px_rgba(220,38,38,0.5)]"
                  style={{ width: `${match.prediction.total_over_2_5}%` }}
                ></div>
                <div
                  className="bg-yellow-500 h-full rounded-r-full"
                  style={{
                    width: `${(100 - match.prediction.total_over_2_5).toFixed(1)}%`,
                  }}
                ></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 3. СТАТИСТИКА */}
      <div className="bg-gray-900 rounded-[40px] p-10 md:p-16 border border-gray-800 shadow-xl">
        <h2 className="text-xs font-black text-white opacity-40 uppercase tracking-[0.5em] mb-16 text-center">
          Deep Statistical Comparison
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-16 md:gap-24">
          <div className="space-y-10">
            <div className="text-center mb-8">
              <span className="inline-block bg-green-500/10 border border-green-500/30 text-green-500 text-[11px] font-black uppercase tracking-widest px-6 py-2.5 rounded-full">
                Атакующий потенциал
              </span>
            </div>
            <StatBar
              label="В среднем забито"
              h={match.homeTeam.stats_last_5.gf}
              a={match.awayTeam.stats_last_5.gf}
              color="bg-green-500"
            />
            <StatBar
              label="Созданный xG"
              h={match.homeTeam.stats_last_5.xg_for}
              a={match.awayTeam.stats_last_5.xg_for}
              color="bg-green-500"
            />
            <StatBar
              label="Глубокие атаки"
              h={match.homeTeam.stats_last_5.deep}
              a={match.awayTeam.stats_last_5.deep}
              color="bg-green-500"
            />
          </div>
          <div className="space-y-10">
            <div className="text-center mb-8">
              <span className="inline-block bg-red-600/10 border border-red-600/30 text-red-500 text-[11px] font-black uppercase tracking-widest px-6 py-2.5 rounded-full">
                Надежность обороны
              </span>
            </div>
            <StatBar
              label="В среднем пропущено"
              h={match.homeTeam.stats_last_5.ga}
              a={match.awayTeam.stats_last_5.ga}
              reverse
              color="bg-red-600"
            />
            <StatBar
              label="Допущенный xG"
              h={match.homeTeam.stats_last_5.xg_against}
              a={match.awayTeam.stats_last_5.xg_against}
              reverse
              color="bg-red-600"
            />
            <StatBar
              label="Прессинг (PPDA)"
              h={match.homeTeam.stats_last_5.ppda}
              a={match.awayTeam.stats_last_5.ppda}
              reverse
              color="bg-red-600"
            />
          </div>
        </div>
      </div>

      {/* 4. ПОСЛЕДНИЕ МАТЧИ (ВЕРТИКАЛЬНЫЕ СПИСКИ) */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <HistoryList
          title={`Последние игры: ${match.homeTeam.name_ru || match.homeTeam.name}`}
          matches={match.homeTeam.history}
        />
        <HistoryList
          title={`Последние игры: ${match.awayTeam.name_ru || match.awayTeam.name}`}
          matches={match.awayTeam.history}
        />
      </div>

      {/* 5. ОЧНЫЕ ВСТРЕЧИ (ПОСТРОЧНО) */}
      <div className="bg-gray-900/60 p-8 md:p-12 rounded-[40px] border border-red-600/20 shadow-2xl">
        <h3 className="text-xs font-black text-red-600 uppercase tracking-[0.5em] mb-10 text-center">
          Очные встречи (H2H - Last 5)
        </h3>
        <div className="space-y-6">
          {match.h2h && match.h2h.length > 0 ? (
            match.h2h.map((m, i) => (
              <div
                key={i}
                className="flex items-center justify-between bg-black/40 p-6 rounded-3xl border border-white/5 transition-all hover:border-white/10"
              >
                {/* Команда Хозяев */}
                <span className="flex-1 text-right text-base md:text-lg font-black text-white uppercase truncate px-2">
                  {m.home}
                </span>

                {/* Центральный блок: Дата и Счет */}
                <div className="flex flex-col items-center gap-2 mx-8 min-w-[120px]">
                  <span className="text-[11px] font-black text-white uppercase tracking-[0.2em]">
                    {m.date}
                  </span>
                  <div
                    className={`px-6 py-2 rounded-xl text-2xl font-black italic tracking-tighter font-mono ${getH2HScoreStyle(m.score)}`}
                  >
                    {m.score}
                  </div>
                </div>

                {/* Команда Гостей */}
                <span className="flex-1 text-left text-base md:text-lg font-black text-white uppercase truncate px-2">
                  {m.away}
                </span>
              </div>
            ))
          ) : (
            <p className="text-center py-10 text-gray-700 italic font-black uppercase tracking-widest">
              История встреч не найдена
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

export default MatchDetailPage;
